import { grandTotal, withDiscount } from "../src/totals.js";
import { shippingCost } from "../src/shipping.js";

let failures = 0;
const expect = (actual, want, msg) => {
  if (actual !== want) {
    failures++;
    console.error("FAIL: " + msg + "（期望 " + String(want) + "，实得 " + String(actual) + "）");
  }
};

